package dev.rodrigo.locationlab; import android.content.*; import android.util.Log; import com.google.android.gms.location.*; public class GeofenceReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent i){GeofencingEvent e=GeofencingEvent.fromIntent(i);if(e==null||e.hasError())return;String t=e.getGeofenceTransition()==Geofence.GEOFENCE_TRANSITION_ENTER?"ENTER":e.getGeofenceTransition()==Geofence.GEOFENCE_TRANSITION_EXIT?"EXIT":"OTHER";Log.i("GeofenceLab","Transition "+t+" for "+e.getTriggeringGeofences());} }